// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#include "StdAfx.h"#include "Bloom.h"#include "D3DPostProcess.h"// Taps per stretch iteration. Must match the unrolled loop in HDRStreakStretchPS.static const int s_nStreakTapCount = 8;// Per tap intensity falloff of the first iteration. Later iterations raise it by the tap// count so the combined falloff stays exponential in distance rather than in iteration.static const float s_fStreakDecay = 0.93f;void CBloomStage::Execute(){	FUNCTION_PROFILER_RENDERER();	// Approximate function (1 - r)^4 by a sum of Gaussians: 0.0174*G(0.008,r) + 0.192*G(0.0576,r)	const float sigma1 = sqrtf(0.008f);	const float sigma2 = sqrtf(0.0576f - 0.008f);	PROFILE_LABEL_SCOPE("BLOOM_GEN");	static CCryNameTSCRC techBloomGaussian("HDRBloomGaussian");	static CCryNameR hdrParams0Name("HDRParams0");	int width = m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetWidth();	int height = m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetHeight();	// Note: Just scaling the sampling offsets depending on the resolution is not very accurate but works acceptably#if defined(USE_CRY_ASSERT)	int widthHalfRes = (m_graphicsPipelineResources.m_pTexHDRTarget->GetWidth() + 1) / 2;	int widthQuarterRes = (widthHalfRes + 1) / 2;	CRY_ASSERT(m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetWidth() == widthQuarterRes);#endif	float scaleW = ((float)width / 400.0f) / (float)width;	float scaleH = ((float)height / 225.0f) / (float)height;	// TODO: Compute shader! because the targets are not compressed / able anyway, and we can half resource allocation)	SamplerStateHandle samplerBloom = (m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetWidth() == 400 && m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetHeight() == 225) ? EDefaultSamplerStates::PointClamp : EDefaultSamplerStates::LinearClamp;	// Pass 1 Horizontal	if (m_pass1H.IsDirty())	{		m_pass1H.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass1H.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass1H.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, 0);		m_pass1H.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass1H.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass1H.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass1H.SetSampler(0, samplerBloom);	}	m_pass1H.BeginConstantUpdate();	m_pass1H.SetConstant(hdrParams0Name, Vec4(scaleW, 0, 0, 0), eHWSC_Pixel);	m_pass1H.Execute();	// Pass 1 Vertical	if (m_pass1V.IsDirty())	{		m_pass1V.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass1V.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass1V.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, 0);		m_pass1V.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass1V.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass1V.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass1V.SetSampler(0, samplerBloom);	}	m_pass1V.BeginConstantUpdate();	m_pass1V.SetConstant(hdrParams0Name, Vec4(0, scaleH, 0, 0), eHWSC_Pixel);	m_pass1V.Execute();	// Pass 2 Horizontal	if (m_pass2H.IsDirty())	{		m_pass2H.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass2H.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass2H.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, 0);		m_pass2H.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass2H.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass2H.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass2H.SetSampler(0, samplerBloom);	}	m_pass2H.BeginConstantUpdate();	m_pass2H.SetConstant(hdrParams0Name, Vec4((sigma2 / sigma1) * scaleW, 0, 0, 0), eHWSC_Pixel);	m_pass2H.Execute();	// Pass 2 Vertical	if (m_pass2V.IsDirty())	{		m_pass2V.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass2V.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass2V.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, g_HWSR_MaskBit[HWSR_SAMPLE0]);		m_pass2V.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRFinalBloom);		m_pass2V.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass2V.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass2V.SetTexture(1, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass2V.SetSampler(0, samplerBloom);	}	m_pass2V.BeginConstantUpdate();	m_pass2V.SetConstant(hdrParams0Name, Vec4(0, (sigma2 / sigma1) * scaleH, 0, 0), eHWSC_Pixel);	m_pass2V.Execute();	ExecuteStreaks();	ExecuteHalation();}// Aperture diffraction streaks (sunstars).//// Runs after the bloom chain, which leaves both quarter resolution HDR scratch targets free:// $HDRTarget 1/4b holds the thresholded sources and $HDRTarget 1/4a is the ping-pong buffer,// so the streaks cost no permanent memory of their own. The half resolution HDR scene is// still intact at this point (the sun shafts stage reads it afterwards) and serves as the// threshold input. The last stretch iteration blends straight into $HDRFinalBloom, so the// streaks travel through the existing bloom composition instead of a second tone-map hook.void CBloomStage::ExecuteStreaks(){	if (!CRenderer::CV_r_HDRStreaks)		return;	CHDRStreaks* pStreaksTech = static_cast<CHDRStreaks*>(PostEffectMgr()->GetEffect(EPostEffectID::HDRStreaks));	if (pStreaksTech == nullptr)		return;	SHDRStreaksParams streakParams = pStreaksTech->GetParams();	// r_HDRStreaks 2: diagnostic force mode - full strength, low threshold, eight spikes,	// independent of any game code driving the params.	if (CRenderer::CV_r_HDRStreaks == 2)	{		streakParams.bActive = true;		streakParams.fAmount = 1.0f;		streakParams.nDirectionCount = 8;		streakParams.fAngle = 0.4f;		streakParams.fThreshold = 0.5f;		streakParams.fLength = 0.6f;	}	// Two independent effects share this pass block: the iris diffraction spikes and the	// anamorphic horizontal flare thrown by a cylindrical front element. Either one alone is	// enough to run the block; only both being off skips it.	const bool bBlade = streakParams.bActive && streakParams.fAmount >= 0.001f && streakParams.nDirectionCount >= 4;	const bool bAnamorphic = streakParams.fAnamorphicAmount >= 0.001f;	if (!bBlade && !bAnamorphic)		return;	PROFILE_LABEL_SCOPE("HDR_STREAKS");	static CCryNameTSCRC techStreakThreshold("HDRStreakThreshold");	static CCryNameTSCRC techStreakStretch("HDRStreakStretch");	static CCryNameR streakParams0Name("StreakParams0");	static CCryNameR streakParams1Name("StreakParams1");	static CCryNameR streakParams2Name("StreakParams2");	CTexture* pStreakSource = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1];	CTexture* pStreakPingPong = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0];	const float fTexelScaleX = 1.0f / (float)pStreakSource->GetWidth();	const float fTexelScaleY = 1.0f / (float)pStreakSource->GetHeight();	// The tone mapper blends the bloom target in with weight bloomAmount * 0.3 / 8 (about	// 0.004 at the default TOD bloom of 0.1). Anything added to the bloom target inherits	// that crush, so divide it back out - the streaks then keep the same on-screen energy	// regardless of the scene's bloom setting.	Vec4 vHDRSetupParams[5];	gEnv->p3DEngine->GetHDRSetupParams(vHDRSetupParams);	const float fBloomCompositeWeight = clamp_tpl(vHDRSetupParams[1].x / 8.0f, 0.0005f, 1.0f);	if (bBlade)	{		// The Count param carries the SPIKE count (even by construction: N for even blade		// counts, 2N for odd). Each pass draws a symmetric line = two opposed spikes, so the		// lines span 180 degrees and there are half as many passes as spikes.		const int nLineCount = clamp_tpl(streakParams.nDirectionCount / 2, 2, kMaxStreakDirections);		// Threshold. The knee is a quarter of the threshold, wide enough to stop the sources		// popping in and out between frames but far too narrow to catch a merely bright sky.		if (m_passStreakThreshold.IsDirty())		{			m_passStreakThreshold.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);			m_passStreakThreshold.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);			m_passStreakThreshold.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakThreshold, 0);			m_passStreakThreshold.SetRenderTarget(0, pStreakSource);			m_passStreakThreshold.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);			m_passStreakThreshold.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[0][0]);			m_passStreakThreshold.SetSampler(0, EDefaultSamplerStates::LinearClamp);		}		m_passStreakThreshold.BeginConstantUpdate();		m_passStreakThreshold.SetConstant(streakParams1Name, Vec4(streakParams.fThreshold, max(streakParams.fThreshold * 0.25f, 0.01f), 0, 0), eHWSC_Pixel);		m_passStreakThreshold.Execute();		// Directional stretch. The rays are evenly spread over the full circle and rotate with		// the blade phase; each one is grown by a chain of exponentially widening blurs.		// Perceived spike length is governed by how slowly the tail decays, not just by the		// sampling reach: short stubby spikes at length 0 (decay 0.55 per tap) grow into long		// persistent tails at length 1 (decay 0.95), while the stride widens the footprint.		const float fBaseStride = 0.5f + 2.0f * streakParams.fLength;		const float fLengthDecay = 0.55f + 0.40f * clamp_tpl(streakParams.fLength, 0.0f, 1.0f);		const float fOutputScale = streakParams.fAmount / ((float)nLineCount * fBloomCompositeWeight);		for (int direction = 0; direction < nLineCount; ++direction)		{			const float fAngle = streakParams.fAngle + (float)direction * (PI / (float)nLineCount);			const float fDirX = cosf(fAngle);			const float fDirY = sinf(fAngle);			float fStride = fBaseStride;			float fDecay = fLengthDecay;			for (int iteration = 0; iteration < kStreakIterations; ++iteration)			{				const bool bLastIteration = (iteration == kStreakIterations - 1);				CFullscreenPass& pass = m_passStreakStretch[direction][iteration];				if (pass.IsDirty())				{					const uint64 nBlendState = bLastIteration ? (GS_BLSRC_ONE | GS_BLDST_ONE) : 0;					pass.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);					pass.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);					pass.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakStretch, 0);					pass.SetRenderTarget(0, bLastIteration ? m_graphicsPipelineResources.m_pTexHDRFinalBloom : pStreakPingPong);					pass.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A | nBlendState);					pass.SetTexture(0, (iteration == 0) ? pStreakSource : pStreakPingPong);					pass.SetSampler(0, EDefaultSamplerStates::LinearClamp);				}				pass.BeginConstantUpdate();				pass.SetConstant(streakParams0Name, Vec4(fDirX * fTexelScaleX, fDirY * fTexelScaleY, fStride, bLastIteration ? fOutputScale : 1.0f), eHWSC_Pixel);				pass.SetConstant(streakParams1Name, Vec4(0, 0, fDecay, 0), eHWSC_Pixel);				// Untinted: the diffraction spikes keep the source's own colour.				pass.SetConstant(streakParams2Name, Vec4(1.0f, 1.0f, 1.0f, 0.0f), eHWSC_Pixel);				pass.Execute();				fStride *= (float)s_nStreakTapCount;				fDecay = powf(fDecay, (float)s_nStreakTapCount);			}		}	}	// Anamorphic horizontal flare. A cylindrical front element throws one long tinted line	// across the frame instead of a star, so this is a single horizontal march - but a much	// longer one: three iterations of 8 taps span 8^3 tap distances, the whole frame width.	if (bAnamorphic)	{		PROFILE_LABEL_SCOPE("ANAMORPHIC_FLARE");		// Own threshold pass into pStreakSource. The blade pass, if it ran at all, has already		// consumed its own thresholded copy, so the scratch target is free to be rewritten.		if (m_passAnamorphicThreshold.IsDirty())		{			m_passAnamorphicThreshold.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);			m_passAnamorphicThreshold.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);			m_passAnamorphicThreshold.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakThreshold, 0);			m_passAnamorphicThreshold.SetRenderTarget(0, pStreakSource);			m_passAnamorphicThreshold.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);			m_passAnamorphicThreshold.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[0][0]);			m_passAnamorphicThreshold.SetSampler(0, EDefaultSamplerStates::LinearClamp);		}		m_passAnamorphicThreshold.BeginConstantUpdate();		m_passAnamorphicThreshold.SetConstant(streakParams1Name, Vec4(streakParams.fAnamorphicThreshold, max(streakParams.fAnamorphicThreshold * 0.25f, 0.01f), 0, 0), eHWSC_Pixel);		m_passAnamorphicThreshold.Execute();		const float fFlareLength = clamp_tpl(streakParams.fAnamorphicLength, 0.0f, 1.0f);		float fStride = 1.0f + 3.0f * fFlareLength;		float fDecay = 0.60f + 0.38f * fFlareLength;		const float fFlareScale = streakParams.fAnamorphicAmount / fBloomCompositeWeight;		const Vec4 vTint(streakParams.vAnamorphicTint.x, streakParams.vAnamorphicTint.y, streakParams.vAnamorphicTint.z, 0.0f);		for (int iteration = 0; iteration < kAnamorphicIterations; ++iteration)		{			const bool bLastIteration = (iteration == kAnamorphicIterations - 1);			CFullscreenPass& pass = m_passAnamorphicStretch[iteration];			// Three iterations need a real ping-pong: source -> pingpong -> source -> bloom.			// Reading and writing the same scratch target in one pass is undefined.			CTexture* pIterSource = (iteration % 2 == 0) ? pStreakSource : pStreakPingPong;			CTexture* pIterTarget = bLastIteration ? m_graphicsPipelineResources.m_pTexHDRFinalBloom			                                       : ((iteration % 2 == 0) ? pStreakPingPong : pStreakSource);			if (pass.IsDirty())			{				const uint64 nBlendState = bLastIteration ? (GS_BLSRC_ONE | GS_BLDST_ONE) : 0;				pass.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);				pass.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);				pass.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakStretch, 0);				pass.SetRenderTarget(0, pIterTarget);				pass.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A | nBlendState);				pass.SetTexture(0, pIterSource);				pass.SetSampler(0, EDefaultSamplerStates::LinearClamp);			}			pass.BeginConstantUpdate();			pass.SetConstant(streakParams0Name, Vec4(fTexelScaleX, 0.0f, fStride, bLastIteration ? fFlareScale : 1.0f), eHWSC_Pixel);			pass.SetConstant(streakParams1Name, Vec4(0, 0, fDecay, 0), eHWSC_Pixel);			// The coating's colour is applied once, on the pass that reaches the bloom target.			pass.SetConstant(streakParams2Name, bLastIteration ? vTint : Vec4(1.0f, 1.0f, 1.0f, 0.0f), eHWSC_Pixel);			pass.Execute();			fStride *= (float)s_nStreakTapCount;			fDecay = powf(fDecay, (float)s_nStreakTapCount);		}	}}// Film halation.//// Light from a source bright enough to overload the emulsion passes through it, reflects off// the film base and re-exposes the emulsion from behind. The red-sensitive layer sits deepest,// so the re-exposure reads red-orange; it is much wider than the core itself and its edge is// soft. Halation is a property of the FILM STOCK, not of the lens, so unlike the diffraction// streaks nothing here follows the f-number.//// Runs after ExecuteStreaks so the two quarter resolution HDR scratch targets are free again,// and blends into $HDRFinalBloom through the same bloom-weight compensation the streaks use.void CBloomStage::ExecuteHalation(){	if (!CRenderer::CV_r_HDRHalation)		return;	CHDRHalation* pHalationTech = static_cast<CHDRHalation*>(PostEffectMgr()->GetEffect(EPostEffectID::HDRHalation));	if (pHalationTech == nullptr)		return;	SHDRHalationParams halationParams = pHalationTech->GetParams();	// r_HDRHalation 2: diagnostic force mode - full strength, low threshold, wide halo,	// independent of any game code driving the params.	if (CRenderer::CV_r_HDRHalation == 2)	{		halationParams.fAmount = 1.0f;		halationParams.fThreshold = 0.5f;		halationParams.fRadius = 0.7f;	}	if (halationParams.fAmount < 0.001f)		return;	PROFILE_LABEL_SCOPE("HDR_HALATION");	static CCryNameTSCRC techStreakThreshold("HDRStreakThreshold");	static CCryNameTSCRC techStreakStretch("HDRStreakStretch");	static CCryNameR streakParams0Name("StreakParams0");	static CCryNameR streakParams1Name("StreakParams1");	static CCryNameR streakParams2Name("StreakParams2");	CTexture* pHalationSource = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1];	CTexture* pHalationTemp = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0];	const float fTexelScaleX = 1.0f / (float)pHalationSource->GetWidth();	const float fTexelScaleY = 1.0f / (float)pHalationSource->GetHeight();	// Same bloom-weight divide as the streaks: the tone mapper blends the bloom target in with	// weight bloomAmount * 0.3 / 8, so anything added here inherits that crush and has to have	// it divided back out to keep a constant on-screen energy.	Vec4 vHDRSetupParams[5];	gEnv->p3DEngine->GetHDRSetupParams(vHDRSetupParams);	const float fBloomCompositeWeight = clamp_tpl(vHDRSetupParams[1].x / 8.0f, 0.0005f, 1.0f);	const float fRadius01 = clamp_tpl(halationParams.fRadius, 0.0f, 1.0f);	// 1. Threshold into the scratch target. Same soft knee (a quarter of the threshold) as the	//    streaks: wide enough to stop sources popping between frames, far too narrow to catch	//    a merely bright sky - which is exactly the point, a sky must not halate.	if (m_passHalationThreshold.IsDirty())	{		m_passHalationThreshold.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_passHalationThreshold.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_passHalationThreshold.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakThreshold, 0);		m_passHalationThreshold.SetRenderTarget(0, pHalationSource);		m_passHalationThreshold.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_passHalationThreshold.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[0][0]);		m_passHalationThreshold.SetSampler(0, EDefaultSamplerStates::LinearClamp);	}	m_passHalationThreshold.BeginConstantUpdate();	m_passHalationThreshold.SetConstant(streakParams1Name, Vec4(halationParams.fThreshold, max(halationParams.fThreshold * 0.25f, 0.01f), 0, 0), eHWSC_Pixel);	m_passHalationThreshold.Execute();	// 2. Wide separable spread, horizontal then vertical, through the streak stretch shader	//    with an isotropic (unrotated) direction. That shader's tap stride is what actually	//    sets the halo's width: CGaussianBlurPass cannot, because its 16 bilinear taps are	//    pinned to +-8 texels no matter how large its distribution gets. At radius 0.5 the	//    stride is 7 quarter-res texels, so the 7 taps per side reach 49 texels ~ 196 full-res	//    pixels on a 1080p frame, for a halo sigma of about 27 texels ~ 109 pixels. The bloom	//    core next to it sits at roughly 24 pixels, so the halo reads about four times wider.	const float fSpreadStride = 2.0f + 10.0f * fRadius01;	// Near-flat per tap decay: emulsion scatter has no sharp falloff, and a flat weight set	// puts the mass out at the far taps, which is where the halo has to be seen.	const float fSpreadDecay = 0.90f;	for (int axis = 0; axis < 2; ++axis)	{		const bool bHorizontal = (axis == 0);		CFullscreenPass& pass = bHorizontal ? m_passHalationSpreadH : m_passHalationSpreadV;		if (pass.IsDirty())		{			pass.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);			pass.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);			pass.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakStretch, 0);			pass.SetRenderTarget(0, bHorizontal ? pHalationTemp : pHalationSource);			pass.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);			pass.SetTexture(0, bHorizontal ? pHalationSource : pHalationTemp);			pass.SetSampler(0, EDefaultSamplerStates::LinearClamp);		}		pass.BeginConstantUpdate();		pass.SetConstant(streakParams0Name, Vec4(bHorizontal ? fTexelScaleX : 0.0f, bHorizontal ? 0.0f : fTexelScaleY, fSpreadStride, 1.0f), eHWSC_Pixel);		pass.SetConstant(streakParams1Name, Vec4(0, 0, fSpreadDecay, 0), eHWSC_Pixel);		// Untinted here - the stock's colour is applied once, on the composite.		pass.SetConstant(streakParams2Name, Vec4(1.0f, 1.0f, 1.0f, 0.0f), eHWSC_Pixel);		pass.Execute();	}	// 3. Round the profile off. The spread above lands 15 discrete taps per axis, which on a	//    small source shows as a cross of ticks; a couple of narrow Gaussian passes smear the	//    gaps between them into the soft continuous edge halation actually has. The	//    distribution is the Gaussian's rho in texels over a FIXED +-8 texel footprint, so it	//    only controls the SHAPE: below ~3 the kernel is too peaked to fill the tap gaps,	//    above ~8 it is flat enough to be a box and hands back a hard edge. 3 -> 8 across the	//    radius range keeps it inside that band.	const float fDistribution = 3.0f + 5.0f * fRadius01;	for (int iteration = 0; iteration < kHalationBlurIterations; ++iteration)		m_passHalationBlur.Execute(pHalationSource, pHalationTemp, 1.0f, fDistribution, false);	// 4. Composite into the bloom target. The stretch shader is reused with a ZERO step, so all	//    15 taps land on the same texel and the normalised sum is a plain tinted sample.	//	//    The energy conserving blur spreads a source over thousands of texels, which leaves the	//    halo far dimmer per pixel than the core it came from - correct as physics, invisible in	//    practice. The gain below puts it back at the strength an overloaded frame really shows,	//    so amount 1 is an obvious red-orange glow rather than a hint of one.	const float fHalationGain = 8.0f;	const float fOutputScale = halationParams.fAmount * fHalationGain / fBloomCompositeWeight;	const Vec4 vTint(halationParams.vTint.x, halationParams.vTint.y, halationParams.vTint.z, 0.0f);	if (m_passHalationComposite.IsDirty())	{		m_passHalationComposite.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_passHalationComposite.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_passHalationComposite.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakStretch, 0);		m_passHalationComposite.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRFinalBloom);		m_passHalationComposite.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A | GS_BLSRC_ONE | GS_BLDST_ONE);		m_passHalationComposite.SetTexture(0, pHalationSource);		m_passHalationComposite.SetSampler(0, EDefaultSamplerStates::LinearClamp);	}	m_passHalationComposite.BeginConstantUpdate();	m_passHalationComposite.SetConstant(streakParams0Name, Vec4(0.0f, 0.0f, 0.0f, fOutputScale), eHWSC_Pixel);	m_passHalationComposite.SetConstant(streakParams1Name, Vec4(0, 0, 1.0f, 0), eHWSC_Pixel);	m_passHalationComposite.SetConstant(streakParams2Name, vTint, eHWSC_Pixel);	m_passHalationComposite.Execute();}